import fs from 'fs';
import { generateBoxArtSvg } from './generator_helpers.js';

function writeConsoleFile(filename, varName, games) {
  const code = `import { VideoGameItem } from '../../types';

export const ${varName}: VideoGameItem[] = ${JSON.stringify(games, null, 2)};
`;
  fs.writeFileSync(filename, code, 'utf-8');
  console.log(`Wrote ${games.length} games to ${filename}`);
}

function mapGames(rawList, consoleKey, mainPlatform = 'Nintendo') {
  return rawList.map(([title, dev, year, genres, themes, perspective, quote, pegi, franchise, bg, accent, icon]) => ({
    id: `${consoleKey.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')}`,
    title,
    developer: dev,
    releaseYear: year,
    genres,
    themes,
    perspective,
    mainPlatform,
    platforms: [consoleKey],
    iconicQuote: quote,
    coverUrl: generateBoxArtSvg({
      title,
      consoleKey,
      developer: dev,
      year,
      genre: genres[0],
      pegi,
      themeBg: bg,
      accentColor: accent,
      iconSymbol: icon
    }),
    pegi,
    gameModes: ['Giocatore singolo'],
    franchise
  }));
}

